from typing import Dict, Any

def get_quai_dam_khach_san_masterpiece_story(title: str = '') -> Dict[str, Any]:
    story_title = title if title else "Khách Sạn Nửa Đêm: 10 Quy Tắc Sinh Tồn Ca Trực Phòng Số 4"
    part1_full = "Đúng mười một giờ đêm ngày đầu tiên nhận việc trực ca đêm tại khách sạn cổ Bạch Ngân, người quản lý già đặt chùm chìa khóa đồng rỉ sét lên quầy lễ tân rồi vội vã rời đi trước khi cửa kính tự động khóa chặt. Đúng mười một giờ đêm, người quản lý già trao vào tay tôi một chùm chìa khóa bằng đồng rỉ sét nặng trịch.\n\nTrước khi vội vã rời khỏi sảnh khách sạn Bạch Ngân, ông ta khựng lại trước cửa kính xoay, quay phắt người lại nhìn tôi bằng đôi mắt đục ngầu đầy vẻ sợ hãi: \"Cậu thanh niên, lương ca đêm của cậu là năm trăm nghìn một đêm, cao gấp ba lần các khách sạn thông thường khác ngoài phố. Nhưng để sống sót lành lặn nhận được số tiền đó vào sáng mai, cậu phải học thuộc lòng từng chữ trong tờ giấy dán dưới gầm bàn lễ tân. Tuyệt đối không được làm sai, dù chỉ là một chi tiết nhỏ nhất!\"\n\nTiếng còi xe cuối cùng ngoài đường lớn dần lịm đi trong màn đêm buốt giá, bỏ lại tôi một mình giữa đại sảnh thênh thang ngập trong ánh đèn vàng vọt lờ mờ.\n\nKhách sạn Bạch Ngân là một tòa nhà kiến trúc kiểu Pháp cổ kính xây dựng từ những năm đầu thế kỷ trước, nằm lọt thỏm sâu bên trong một con ngõ cụt tĩnh mịch. Ban ngày, nơi này là điểm dừng chân yên tĩnh cho những vị khách công tác đường xa. Nhưng khi màn đêm buông xuống, bóng tối bao trùm lấy từng bức tường ẩm mốc loang lổ, tạo nên một bầu không khí u ám, ngột ngạt đến lạ thường.\n\nTôi cúi người xuống gầm bàn quầy lễ tân bằng gỗ lim đen bóng, quả nhiên nhìn thấy một tờ giấy A4 đã ố vàng vì thời gian, các góc mép bị cháy xém loang lổ như vừa trải qua một trận hỏa hoạn kinh hoàng. Trên đầu trang giấy viết bằng nét bút dạ đỏ đậm nét, gạch chân ba lần:\n\n\"BẢN QUY TẮC SINH TỒN BẮT BUỘC DÀNH CHO NHÂN VIÊN TRỰC CA ĐÊM (00:00 - 06:00)\"\n\nQuy tắc số 1: Sau mười hai giờ đêm, toàn bộ cửa chính bằng kính xoay phải được kéo then sắt khóa chặt từ bên trong. Nếu có khách bấm chuông xin thuê phòng sau mốc thời gian này, chỉ được phép hé ô kính nhỏ để quan sát nhân diện. Nếu người đó mặc áo mưa màu vàng chanh hoặc mang giày thể thao màu đỏ ướt sũng bùn đất, hãy lập tức đóng chặt ô kính lại và nói: \"Hôm nay khách sạn đã hết phòng\". Dù họ có đập cửa van xin hay chửi bới thế nào, tuyệt đối không được mở chốt khóa.\n\nQuy tắc số 2: Khách sạn Bạch Ngân chỉ có ba tầng lầu với tổng cộng hai mươi mốt phòng nghỉ phục vụ khách. Nếu trên bảng hiển thị thang máy hoặc màn hình camera hiện lên tầng số 4, đừng hoảng loạn la hét. Hãy bấm nút tắt màn hình số 3 trên bàn điều khiển trong vòng năm giây, sau đó nhắm chặt mắt lại đếm chậm rãi từ một đến mười. Khi mở mắt ra, mọi thứ sẽ trở lại trạng thái bình thường.\n\nQuy tắc số 3: Sau một giờ sáng, nếu nghe thấy tiếng bước chân lẹp xẹp ướt sũng đi lại trên hành lang tầng hai, hãy cầm theo chiếc bình xịt phòng hương sả chanh đặt trên kệ gỗ đi lên kiểm tra. Nếu nhìn thấy một vệt nước kéo dài dẫn vào phòng 204, đừng gõ cửa. Hãy xịt ba nhát tinh dầu sả chanh trước cửa phòng rồi quay lưng đi thẳng xuống sảnh. Trong suốt quá trình này, cấm tuyệt đối không được quay đầu nhìn lại phía sau lưng dù có nghe thấy tiếng ai gọi tên mình.\n\nQuy tắc số 4: Khách sạn hoàn toàn không có phòng nào mang số 4. Các phòng ở tầng một được đánh số từ 101 đến 107, tầng hai từ 201 đến 207, tầng ba từ 301 đến 307. Nếu có bất kỳ vị khách nào từ trên lầu đi xuống quầy lễ tân trả chìa khóa phòng số 4 hoặc xin mượn chìa khóa phòng số 4, tuyệt đối không được nhìn thẳng vào mắt họ. Hãy cúi gằm mặt xuống sổ sách và trả lời đúng một câu: \"Khách sạn chúng tôi không có phòng số 4, xin quý khách kiểm tra lại số phòng trên chìa khóa\". Sau đó, hãy chờ cho đến khi tiếng bước chân của họ biến mất hoàn toàn mới được ngẩng đầu lên.\n\nQuy tắc số 5: Chiếc gương lớn mạ vàng treo đối diện quầy lễ tân chỉ được dùng để chỉnh trang y phục vào ban ngày. Sau hai giờ sáng, nếu nhìn vào gương và thấy hình ảnh phản chiếu của mình đang mỉm cười hoặc nháy mắt trong khi bản thân không làm vậy, hãy lập tức cúi đầu úp mặt xuống bàn và niệm ba lần câu: \"Cõi âm có lối, cõi dương có đường, nước sông không phạm nước giếng\". Sau ba phút, hiện tượng này sẽ tự biến mất.\n\nTôi nuốt nước bọt cái ực, sống lưng bỗng chốc dâng lên một luồng ớn lạnh gai người. Cứ ngỡ đây chỉ là trò đùa dai của đám nhân viên cũ bày ra để dọa nạt người mới đến nhận việc, tôi đặt tờ giấy lại chỗ cũ rồi bật ấm nước pha một ly cà phê đen đặc không đường để chống lại cơn buồn ngủ đang kéo đến trĩu nặng hai mi mắt.\n\nĐúng không giờ ba mươi phút sáng.\n\nKhông gian tĩnh lặng như tờ, chỉ có tiếng kim đồng hồ quả lắc bằng đồng treo tường kêu tích tắc từng nhịp khô khốc và tiếng gió rít qua những khe cửa sổ gỗ cũ kỹ. Bất thình lình, từ phía cửa kính lớn bên ngoài sảnh vang lên ba tiếng gõ dồn dập, mạnh mẽ: \"Cộc... cộc... cộc!\"\n\nTiếng gõ cửa vang lên khô khốc giữa đêm khuya thanh vắng khiến tim tôi suýt chút nữa nhảy vọt ra khỏi lồng ngực.\n\nTôi hít một hơi thật sâu để lấy lại bình tĩnh, chầm chậm bước từng bước thận trọng tới gần cửa kính, nhớ lại quy tắc số 1 và khẽ hé ô kính nhỏ kiểm tra tình hình bên ngoài.\n\nBên ngoài trời đang đổ mưa phùn lất phất, không khí se lạnh buốt giá. Đứng dưới ánh đèn đường vàng vọt chập chờn là một bóng người cao gầy, khoác trên mình một chiếc áo mưa nylon màu vàng chanh trùm kín mít từ đỉnh đầu xuống tận bắp chân. Nhưng điều khiến mồ hôi lạnh trên trán tôi túa ra như tắm chính là đôi chân của người đó. Hắn ta không đi ủng cao su đi mưa, mà đang mang một đôi giày thể thao màu đỏ tươi ướt sũng bùn đất, từng giọt nước đỏ sẫm như máu từ ống quần hắn đang nhỏ tong tòng xuống bậc thềm đá hoa cương trắng toát!\n\nHai bàn tay tôi run rẩy dữ dội đến mức suýt đánh rơi chiếc chốt cài. Tôi vội vàng giật mạnh ô kính đóng sập lại, cài chặt then sắt, rồi cố gắng hít thở thật sâu để giữ cho giọng nói không bị run rẩy: \"Xin lỗi quý khách... Đêm nay khách sạn chúng tôi đã hết sạch phòng nghỉ rồi ạ!\"\n\nBên ngoài cánh cửa lớn lập tức rơi vào một khoảng im lặng chết chóc suốt ba mươi giây dài đằng đẵng.\n\nSau đó, một tràng cười the thé, the thé như tiếng móng tay sắc nhọn cào rào rạo vào mặt bảng kính vang lên ngay sát bên tai tôi: \"Hết phòng sao? Ta thấy trên lầu ba... căn phòng 304 ở góc hành lang vẫn còn hé mở cửa sổ và sáng đèn màu đỏ mà...\"\n\nTiếng cười rùng rợn kéo dài lê thê rồi lịm dần theo tiếng bước chân lẹp xẹp ướt sũng đi vòng ra phía con ngõ tối tăm sau lưng khách sạn. Tôi tựa lưng vào cánh cửa sắt lạnh ngắt, thở dốc từng cơn nghẹn ngào, hai đầu gối nhũn ra đến mức không đứng vững nổi. Những quy tắc quái dị dán dưới gầm bàn lễ tân kia không phải là một trò đùa... Chúng chính là lằn ranh mong manh duy nhất ngăn cách giữa sự sống và cái chết trong đêm trực định mệnh này!"
    part2_full = "Kim đồng hồ quả lắc trên tường sảnh chính vừa chỉ qua một giờ mười lăm phút sáng, tiếng chuông điện thoại nội bộ nối từ căn phòng số bốn bỏ trống trên tầng bốn bỗng reo vang. Tôi run rẩy bò lết quay trở lại quầy lễ tân, hai tay bám chặt vào mép bàn gỗ lim để lấy lại chút hơi ấm và sự bình tĩnh cuối cùng.\n\nChiếc đồng hồ quả lắc bằng đồng trên tường điểm đúng một giờ mười lăm phút sáng.\n\nĐúng lúc này, chiếc màn hình camera số 3 đặt ở góc trái bàn lễ tân bỗng nhiên phát ra tiếng xẹt xẹt chói tai như bị nhiễu sóng từ trường cực mạnh. Hình ảnh sảnh chờ vốn đang tối om bỗng nhấp nháy liên tục, rồi chuyển sang một góc quay vô cùng kỳ lạ và xa lạ.\n\nĐó là góc quay bên trong một buồng thang máy cũ kỹ với những bức vách kim loại hoen rỉ ố vàng, những vết xước dài ngoằng như móng tay cào cấu khắp các vách ngăn. Nhưng điều quái đản nhất là trên bảng hiển thị tầng của thang máy, ngọn đèn đỏ đang sáng rực ở vị trí một con số mà khách sạn này chưa từng tồn tại trên bản vẽ: Tầng số 4!\n\nBên trong buồng thang máy ngột ngạt ấy, một người phụ nữ mặc chiếc váy dạ hội màu trắng đã ngả vàng rách rưới đang đứng quay lưng lại với ống kính camera. Mái tóc đen dài rũ rượi xõa xuống tận thắt lưng, ướt sũng nước và dính bết vào hai bên bờ vai gầy guộc. Từng giọt nước đen ngòm từ gấu váy của người phụ nữ ấy nhỏ tí tách xuống sàn kim loại của thang máy.\n\n\"Quy tắc số 2!\" Tiếng nói cảnh báo trong tiềm thức tôi gào thét dữ dội.\n\nTôi giật nảy mình nhớ lại bản hướng dẫn sinh tồn dán dưới gầm bàn: \"Nếu trên bảng hiển thị thang máy hoặc màn hình camera hiện lên tầng số 4... Hãy bấm nút tắt màn hình số 3 trên bàn điều khiển trong vòng năm giây, sau đó nhắm chặt mắt lại đếm chậm rãi từ một đến mười!\"\n\nMột... hai... ngón tay tôi run bần bật lao tới công tắc nguồn của màn hình số 3. Ba... bốn...\n\nNgay khoảnh khắc đầu ngón tay tôi vừa chạm vào nút bấm nhựa cứng, người phụ nữ trong buồng thang máy bỗng nhiên từ từ xoay đầu lại một góc một trăm tám mươi độ mà toàn bộ cơ thể bên dưới không hề cử động!\n\nDưới mái tóc đen rũ rượi ướt sũng ấy hoàn toàn không có mắt, mũi hay tai của một con người bình thường, mà chỉ là một bề mặt da thịt trơn láng, trắng bệch như sáp nến của xác ướp. Ở chính giữa khuôn mặt dị dạng ấy bỗng nứt toác ra một vết rách đỏ lòm như một chiếc miệng không có môi đang ngoác rộng ra tận hai bên mang tai để lộ hàm răng đen nhánh!\n\n\"Cạch!\" Tôi dồn toàn bộ sức bình sinh đập mạnh lòng bàn tay xuống nút nguồn. Màn hình camera lập tức phụt tắt, chìm vào một màu đen sâu thẳm không đáy.\n\nTôi lập tức nhắm nghiền hai mắt lại thật chặt, hai tay ôm ghì lấy đầu, nghiến chặt răng đếm thầm từng nhịp trong cơn hoảng loạn tột độ: \"Một... hai... ba... bốn... năm... sáu... bảy... tám... chín... mười...\"\n\nXung quanh tôi, bầu không khí bỗng chốc trở nên lạnh buốt thấu xương như thể cả căn phòng vừa bị nhúng vào một hầm ướp đá ngầm. Một luồng gió tanh tưởi thoảng qua sát vành tai tôi, mang theo mùi ẩm mốc của bùn lầy dưới đáy giếng hoang lâu năm không có ánh mặt trời. Nhưng tôi tuyệt đối không dám hé mắt ra dù chỉ nửa milimét cho đến khi tiếng chuông gió treo ngoài cửa chính khẽ leng keng một tiếng thanh mảnh báo hiệu luồng tà khí đã rút đi.\n\nTôi chầm chậm mở mắt ra, lồng ngực phập phồng thở dốc.\n\nBàn lễ tân vẫn ở đó, ly cà phê đen đã nguội ngắt đóng váng từ bao giờ. Màn hình số 3 vẫn tối đen như mực. Tôi đưa tay lên sờ trán, mồ hôi lạnh ướt đầm đìa cả mái tóc và cổ áo. Tôi vừa thoát khỏi lưỡi hái tử thần trong gang tấc chỉ bằng một phần mười giây ngắn ngủi.\n\nThế nhưng, cơn ác mộng của đêm nay dường như mới chỉ vừa bắt đầu khúc dạo đầu nghiệt ngã.\n\nĐúng một giờ bốn mươi phút sáng, từ trên cầu thang gỗ dẫn lên tầng hai, những tiếng bước chân \"bẹp... bẹp... bẹp...\" bắt đầu vang lên rõ mồn một trong không gian tĩnh mịch.\n\nĐó là âm thanh của những bước chân trần trượt trên nền sàn gỗ ướt nước, nặng nề, chậm chạp và dính nhớp, như thể có một thứ gì đó từ dưới đáy hồ sâu vừa ngoi lên và đang lê lết từng bước một trên hành lang ngay phía trên đầu tôi.\n\n\"Quy tắc số 3...\" Tôi run rẩy lật lại tờ giấy sinh tồn, mắt dán chặt vào từng dòng chữ như bám vào chiếc phao cứu sinh cuối cùng: \"Sau một giờ sáng, nếu nghe thấy tiếng bước chân lẹp xẹp ướt sũng đi lại trên hành lang tầng hai, hãy cầm theo chiếc bình xịt phòng hương sả chanh đặt trên kệ gỗ đi lên kiểm tra. Nếu nhìn thấy một vệt nước kéo dài dẫn vào phòng 204, đừng gõ cửa. Hãy xịt ba nhát tinh dầu sả chanh trước cửa phòng rồi quay lưng đi thẳng xuống sảnh. Tuyệt đối không được quay đầu nhìn lại!\"\n\nTôi với tay lấy chai xịt phòng hương sả chanh bằng nhôm đặt trên kệ gỗ sau lưng. Bàn tay nắm chặt lấy thân bình xịt lạnh buốt, tôi nuốt một ngụm nước bọt đắng ngắt rồi từng bước tiến về phía chân cầu thang gỗ tối om om.\n\nMỗi bậc thang gỗ dưới sức nặng của tôi đều phát ra những tiếng cọt kẹt rợn người như tiếng xương khớp gãy vụn.\n\nKhi vừa bước chân lên tới hành lang tầng hai, một cảnh tượng hãi hùng đập thẳng vào mắt tôi dưới ánh đèn ngủ đỏ quạch mờ ảo: Trên mặt sàn gỗ bóng loáng, một vệt nước đen ngòm, sền sệt bốc mùi tanh nồng như mùi cá ươn kéo dài từ chân cầu thang, uốn lượn ngoằn ngoèo qua các phòng rồi dừng lại ngay trước cánh cửa gỗ mang biển số 204!\n\nBên trong căn phòng 204 đóng kín ấy, tiếng nước nhỏ giọt \"tỏng... tỏng... tỏng...\" vang lên đều đặn, kèm theo tiếng thở phì phò nặng nhọc và tiếng rên rỉ nghẹn ngào như của một kẻ đang bị chết đuối dưới đáy nước sâu.\n\nTôi nín thở, tim đập thình thịch như muốn vỡ tung, hai chân run rẩy tiến lại gần cánh cửa phòng 204. Nhớ kỹ lời cảnh báo sống còn trong quy tắc, tôi không dám chạm tay vào nắm đấm cửa bằng đồng, cũng không dám nhìn qua khe hở phía dưới chân sàn. Tôi giơ chiếc bình xịt nhôm lên, nhắm thẳng vào khe cửa phòng xịt mạnh ba nhát liên tiếp:\n\n\"Xì... xì... xì!\"\n\nMùi tinh dầu sả chanh the nồng, cay xè lập tức lan tỏa khắp hành lang, lấn át đi mùi tanh nồng của bùn rêu.\n\nNgay lập tức, từ bên trong căn phòng 204 vang lên một tiếng rít the thé đầy giận dữ và đau đớn tột cùng, tựa như tiếng một con quái thú bị ngọn lửa thiêu đốt da thịt! Mặt gỗ của cánh cửa bỗng nhiên lõm sâu vào một mảng lớn như bị một bàn tay vô hình khổng lồ đấm mạnh từ bên trong hòng phá cửa xông ra!\n\nTôi không dám chần chừ thêm một tích tắc nào, cắn chặt môi quay ngoắt người lại, cắm đầu cắm cổ bước từng bước dứt khoát về phía cầu thang dẫn xuống sảnh.\n\nPhía sau lưng tôi, tiếng móng tay sắc nhọn cào rào rạo trên cánh cửa gỗ vang lên điên cuồng, kèm theo tiếng thì thầm gọi tên tôi nghe quen thuộc đến rợn người: \"Quay lại đây... Cậu thanh niên... quay lại nhìn ta một lần đi... Ta để quên đồ trong này...\"\n\nDù giọng nói ấy có ngọt ngào và ai oán đến đâu, tôi vẫn cắn chặt răng bước thẳng xuống sảnh tầng một, hai mắt nhìn trừng trừng vào bậc thang phía trước. Đến khi hai chân chạm vào nền đá hoa cương của đại sảnh, tiếng cào cửa trên lầu hai mới đột ngột im bặt như chưa từng tồn tại trong cõi trần."
    part3_full = "Ba giờ sáng, toàn bộ đèn hành lang khách sạn Bạch Ngân đồng loạt chuyển sang màu đỏ máu nhợt nhạt, và tiếng bước chân kéo lê ngoài cầu thang bộ bắt đầu tiến thẳng xuống quầy lễ tân. Ba giờ sáng.\n\nKhoảng thời gian u ám, ma mị và tĩnh mịch nhất của một đêm trực kinh hoàng. Cả tòa nhà khách sạn Bạch Ngân dường như bị tách biệt hoàn toàn khỏi thế giới bên ngoài, không một tiếng còi xe, không một bóng người qua lại trên con ngõ cụt tăm tối.\n\nTôi ngồi thu mình sau quầy lễ tân, hai mắt trừng trừng nhìn vào tờ giấy quy tắc sinh tồn dưới ánh nến le lói. Nhưng lúc này, khi quan sát kỹ dưới ánh lửa nến, tôi mới bàng hoàng nhận ra ở phần cuối cùng của trang giấy, có một mục quy tắc số 10 đã bị ai đó dùng mực đỏ gạch xóa nhem nhuốc, chỉ còn sót lại mấy chữ lờ mờ: \"...quy tắc giả mạo... kẻ đến thu dọn đồ...\"\n\nĐúng lúc này, cánh cửa chính bằng kính xoay của khách sạn bỗng nhiên tự động mở toang ra một cách kỳ lạ, phát ra tiếng rít ken két rợn người, dù trước đó tôi đã cài chốt then sắt vô cùng cẩn thận!\n\nMột luồng gió lạnh buốt từ ngoài trời thốc thẳng vào đại sảnh, làm tắt ngúm ngọn đèn chùm pha lê trên trần nhà. Trong bóng tối lờ mờ của ánh trăng rọi qua ô cửa kính, một bóng người từ tốn bước vào sảnh với những bước chân đĩnh đạc.\n\nĐó là một người đàn ông mặc bộ âu phục chỉn chu, tay xách chiếc cặp da đen bóng loáng. Khi bước lại gần quầy lễ tân, dưới ánh sáng mờ ảo của ngọn nến trên bàn, tôi sững sờ nhận ra khuôn mặt của ông ta: Đó chính là người quản lý già đã giao chùm chìa khóa cho tôi lúc mười một giờ đêm!\n\n\"Cậu làm việc tốt lắm, cậu thanh niên.\" Người quản lý già nở một nụ cười ấm áp, hiền từ khác hẳn vẻ mặt hoảng loạn, sợ hãi lúc đầu hôm. Ông ta nhẹ nhàng đặt chiếc cặp da lên mặt bàn, cất giọng trầm ấm quen thuộc: \"Ca trực đêm nay của cậu có thể kết thúc sớm rồi. Tôi quay lại đây để bàn giao ca sớm và thanh toán tiền lương đầy đủ cho cậu. Đưa lại cho tôi chùm chìa khóa đồng và tờ giấy quy tắc dưới gầm bàn đi, cậu có thể về nhà ngủ một giấc thật ngon rồi đấy.\"\n\nVừa nói, ông ta vừa rút từ trong túi áo khoác ra một cọc tiền năm trăm nghìn mới tinh đặt lên mặt bàn trước mặt tôi.\n\nCảm giác nhẹ nhõm và mong muốn được thoát khỏi nơi quỷ quái này suýt chút nữa đã khiến tôi buông lỏng cảnh giác hoàn toàn. Tôi đưa tay định với lấy tờ giấy quy tắc dưới gầm bàn để trao lại cho ông ta.\n\nThế nhưng, ngay khoảnh khắc đầu ngón tay tôi vừa chạm vào góc tờ giấy, ánh mắt tôi vô tình liếc nhìn xuống sàn nhà dưới chân người quản lý.\n\nSàn nhà đá hoa cương sạch bóng phản chiếu ánh trăng rọi qua khung cửa kính lớn. Nhưng trên mặt sàn hoàn toàn trống trơn một cách bất thường... Người quản lý đang đứng sừng sững trước mặt tôi không hề có bóng đen dưới chân!\n\nChưa dừng lại ở đó, chiếc áo khoác dạ của ông ta khô ráo một cách kỳ dị, trong khi ngoài trời mưa phùn đang rơi tầm tã suốt ba tiếng đồng hồ qua, bất kỳ ai bước từ ngoài vào cũng phải ướt sũng vai áo!\n\nSống lưng tôi lập tức lạnh toát như bị một tảng băng ngàn năm đè nặng lên da thịt. Kẻ đang đứng trước mặt tôi không phải là người quản lý già bằng xương bằng thịt!\n\n\"Sao thế hả cậu thanh niên?\" Nụ cười hiền từ trên môi người quản lý bỗng nhiên méo mó đi một cách quái đản, khóe môi ông ta ngoác rộng ra đến tận mang tai, để lộ hai hàng răng nhọn hoắt đen ngòm như răng thú dữ. \"Không muốn lấy tiền lương sao? Mau đưa tờ giấy quy tắc cho ta... Cậu không cần đến nó nữa đâu... Ở lại đây làm khách của phòng số 4 đi...\"\n\nTôi nuốt một ngụm nước bọt cay đắng, bàn tay giấu dưới gầm bàn vội vàng lật mặt sau của tờ giấy A4 ố vàng lên.\n\nỞ mặt sau của tờ giấy, nơi được dán chặt vào mặt dưới tấm gỗ lim bằng keo nến dày cộp, có một dòng chữ viết tay nhỏ xíu bằng máu khô đã chuyển sang màu nâu sẫm:\n\n\"QUY TẮC SỐ 10 THỰC SỰ (BỊ ẨN GIẤU): Nếu người quản lý quay trở lại trước sáu giờ sáng để đòi lại bản quy tắc và chùm chìa khóa, đó chính là 'Thứ Trong Phòng Số 4' giả dạng nhằm thu hồi chứng cứ phong ấn. Tuyệt đối không được giao chìa khóa hay bản quy tắc. Hãy lấy chiếc chìa khóa đồng rỉ sét lớn nhất trong chùm chìa khóa, nhúng vào chén tro tàn của nén hương trên bàn thờ thần tài ở góc sảnh, rồi cắm thẳng vào ổ khóa phụ bằng sắt giấu dưới chân quầy lễ tân. Khi ổ khóa phụ đóng lại, khách sạn sẽ tự động kích hoạt trận địa thanh tẩy bằng ánh sáng!\"\n\nKhoảng cách giữa sự sống và cái chết lúc này chỉ còn tính bằng từng phần trăm giây ngắn ngủi.\n\nCon quái vật đội lốt người quản lý bắt đầu mất kiên nhẫn khi thấy tôi không hề cử động. Bàn tay của hắn bỗng nhiên biến dạng, các ngón tay dài ngoằng ra mọc đầy những chiếc móng vuốt đen dài nhọn hoắt, vươn thẳng qua mặt bàn quầy lễ tân chộp lấy cổ họng tôi!\n\n\"Chết đi cho ta!\" Hắn gầm lên một tiếng rùng rợn xé toạc màng nhĩ, âm thanh tựa như tiếng kêu khóc của hàng trăm linh hồn phát ra từ đáy địa ngục sâu thẳm.\n\nTôi không hề lùi bước hay nhắm mắt chờ chết. Bằng một phản xạ sinh tồn phi thường được trui rèn qua hàng giờ đối mặt với hiểm nguy, tôi cúi gập người xuống né tránh cú vồ chết người của hắn, tay trái túm chặt lấy chùm chìa khóa đồng, tay phải thọc thẳng chiếc chìa khóa to nhất vào lư hương trên bàn thờ thần tài ở góc phòng, quấy mạnh một vòng cho lớp tàn tro hương cổ thụ bám chặt lấy thân chìa khóa rỉ sét.\n\nMóng vuốt sắc nhọn của con quái vật sượt qua vai áo tôi, xé toạc lớp vải dày và để lại năm vết cào rớm máu bỏng rát như bị than hồng dí thẳng vào da thịt.\n\nNhưng tôi đã kịp thời lao mình tới chân quầy lễ tân, cắm mạnh chiếc chìa khóa phủ đầy tro hương vào chiếc ổ khóa phụ bằng sắt đen ngòm giấu kín dưới chân cột gỗ lim!\n\n\"Rắc!\" Một tiếng chuyển động cơ khí kim loại giòn giã vang lên dứt khoát giữa đêm đen.\n\nNgay khoảnh khắc ổ khóa phụ được vặn chặt nửa vòng tròn, toàn bộ hệ thống đèn cao áp dự phòng công suất lớn của khách sạn bỗng nhiên đồng loạt bật sáng rực rỡ chói lòa như ánh mặt trời giữa ban ngày!\n\n\"Aaaa!\"\n\nCon quái vật đội lốt người quản lý rú lên một tiếng thét xé lòng đầy đau đớn khi luồng ánh sáng cực mạnh rọi thẳng vào thân thể ma quái của hắn. Lớp da thịt người giả tạo trên mặt hắn bắt đầu tan chảy nham nhở như sáp nến gặp lửa lớn, bốc lên những làn khói đen kịt tanh tưởi đến nghẹt thở. Trong làn khói đen cuồn cuộn ấy, một bóng đen khổng lồ gầy guộc gầm thét giãy giụa trong đau đớn rồi tan biến hoàn toàn vào hư không, để lại trên sàn nhà đá hoa cương một vũng nước đen ngòm bốc mùi hôi thối nồng nặc.\n\nĐúng lúc này, tiếng chuông đồng hồ quả lắc trên tường ngân vang sáu tiếng dõng dạc, thanh thoát:\n\n\"Đoong... đoong... đoong... đoong... đoong... đoong...\"\n\nSáu giờ sáng.\n\nÁnh bình minh rạng rỡ của một ngày mới bắt đầu chiếu rọi qua khung cửa kính xoay của khách sạn Bạch Ngân, xua tan đi toàn bộ màn đêm u ám, ma mị và những quy tắc sinh tồn quái dị của cõi chết.\n\nTiếng còi xe máy và tiếng cười nói rôm rả của những người đi chợ sớm ngoài con ngõ lớn vọng vào sảnh nghe thân thương, ấm áp và bình yên đến lạ kỳ. Tôi ngồi bệt xuống sàn đá hoa cương lạnh buốt, thở dốc từng cơn nhẹ nhõm, hai bàn tay run run siết chặt lấy chùm chìa khóa đồng đã nguội lạnh.\n\nTôi đã sống sót qua ca trực đêm kinh hoàng nhất trong suốt hai mươi năm cuộc đời mình. Và trên bàn lễ tân, cọc tiền năm trăm nghìn kia đã biến thành một đống tro tàn màu xám trắng lạnh ngắt, minh chứng cho một đêm đối đầu nghẹt thở giữa sự sống của con người và bóng tối quái đàm chốn trần gian."
